/** Namensnennung eines Tatoeba-Originalsatzes (CC BY 2.0 FR). */
function tatoeba(nr: string, benutzer: string, original: string): Herkunft {
  return {
    quelle: "Tatoeba",
    lizenz: "CC BY 2.0 FR",
    autor: benutzer,
    fundstelle: `https://tatoeba.org/fr/sentences/show/${nr} (Original: ${original})`,
  };
}

